Lemma PA_STK : forall (M1 M2 : mem) (Sg : Z -> Prop), (forall a, Sg a -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  forall psx mw rest x,
  PTA.out Sg P 256 -> PTA.out Sg (P + 264) 8 -> PTA.out Sg (PML.ps_bptr psx) (PML.ps_bcap psx) -> PTA.out Sg (PML.ps_sb psx) (PML.ps_scap psx) ->
