Lemma CORE_VEC : forall i j E1 E2 (M1 M2 : mem) psx g1 stk' sb' sc' (Sg : Z -> Prop),
  PSOX.CORE I i E1 M1 (PML.ps_win psx) psx 0 g1 -> PSO.curk (PSO.kind_of j) = false ->
  (forall a, Sg a -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  PTA.out Sg P 248 -> PTA.out Sg (PML.ps_bptr psx) (PML.ps_bcap psx) -> PTA.out Sg E 16 ->
  (forall a, STATIC a -> Sg a) -> (forall a, in_shadow_of (PML.ps_bptr psx) (PML.ps_bcap psx) a -> Sg a) -> PML.ps_bptr psx mod 8 = 0 ->
  L5.u64_at (hl_segs L) M2 (P + 248) sb' -> L5.u64_at (hl_segs L) M2 (P + 256) (sb' + Z.of_nat (length stk')) -> L5.u64_at (hl_segs L) M2 (P + 264) (sb' + sc') ->
  L5.bytes_at (hl_segs L) M2 sb' stk' -> Z.of_nat (length stk') <= sc' -> shadow_cont M2 sb' sc' (Z.of_nat (length stk')) ->
  (forall k, 0 <= k < 272 -> M2 (Z_to_bv 64 (P + k)) <> None) ->
  bptrI j E2 = PML.ps_bptr psx -> bcapI j E2 = PML.ps_bcap psx -> sbI j E2 = sb' -> scapI j E2 = sc' -> PSO.u0 j = PSO.u0 i ->
  (PSOX.retk (PSO.kind_of j) = false -> PSOX.retk (PSO.kind_of i) = false) -> (PSOX.wlk (PSO.kind_of j) = true -> PSOX.wlk (PSO.kind_of i) = true) ->
  (PSO.u0 i = true -> env_agree 60 E1 E2) ->
